package cl.acis.catalogos.service;
import cl.acis.catalogos.dto.*; import cl.acis.catalogos.exception.*; import cl.acis.catalogos.model.*; import cl.acis.catalogos.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional public class CatalogoService {final ClienteRepository clientes;final EquipoRepository equipos;final MotivoRepository motivos;final RutValidator rut;public CatalogoService(ClienteRepository c,EquipoRepository e,MotivoRepository m,RutValidator r){clientes=c;equipos=e;motivos=m;rut=r;}
 public ClienteResponse crearCliente(ClienteRequest r){rut.validar(r.rut());if(clientes.existsByRutIgnoreCase(r.rut()))throw new ReglaNegocioException("El RUT ya está registrado");Cliente c=new Cliente();copy(r,c);return cliente(clientes.save(c));}public List<ClienteResponse> clientes(){return clientes.findAll().stream().map(this::cliente).toList();}public ClienteResponse cliente(Long id){return cliente(getCliente(id));}public ClienteResponse editarCliente(Long id,ClienteRequest r){rut.validar(r.rut());Cliente c=getCliente(id);copy(r,c);return cliente(c);}public void borrarCliente(Long id){getCliente(id).setActivo(false);}
 public EquipoResponse crearEquipo(EquipoRequest r){Equipo e=new Equipo();copy(r,e);return equipo(equipos.save(e));}public List<EquipoResponse> equipos(Long cliente){return (cliente==null?equipos.findAll():equipos.findByClienteId(cliente)).stream().map(this::equipo).toList();}public EquipoResponse equipo(Long id){return equipo(getEquipo(id));}public EquipoResponse editarEquipo(Long id,EquipoRequest r){Equipo e=getEquipo(id);copy(r,e);return equipo(e);}public void borrarEquipo(Long id){getEquipo(id).setActivo(false);}
 public MotivoResponse crearMotivo(MotivoRequest r){MotivoCatalogo m=new MotivoCatalogo();m.setTipo(r.tipo());m.setTexto(r.texto());return motivo(motivos.save(m));}public List<MotivoResponse> motivos(TipoMotivo tipo){return (tipo==null?motivos.findAll():motivos.findByTipo(tipo)).stream().map(this::motivo).toList();}public MotivoResponse motivo(Long id){return motivo(getMotivo(id));}public MotivoResponse editarMotivo(Long id,MotivoRequest r){MotivoCatalogo m=getMotivo(id);m.setTipo(r.tipo());m.setTexto(r.texto());return motivo(m);}public void borrarMotivo(Long id){getMotivo(id).setActivo(false);}
 private void copy(ClienteRequest r,Cliente c){c.setRazonSocial(r.razonSocial());c.setRut(r.rut());c.setContacto(r.contacto());c.setCorreo(r.correo());c.setTelefono(r.telefono());c.setDireccion(r.direccion());c.setSlaHoras(r.slaHoras());}private void copy(EquipoRequest r,Equipo e){e.setClienteId(r.clienteId());e.setTipo(r.tipo());e.setMarca(r.marca());e.setModelo(r.modelo());e.setSerie(r.serie());e.setUbicacion(r.ubicacion());e.setExterior(r.exterior());}private Cliente getCliente(Long id){return clientes.findById(id).orElseThrow(()->new RecursoNoEncontradoException("Cliente no encontrado"));}private Equipo getEquipo(Long id){return equipos.findById(id).orElseThrow(()->new RecursoNoEncontradoException("Equipo no encontrado"));}private MotivoCatalogo getMotivo(Long id){return motivos.findById(id).orElseThrow(()->new RecursoNoEncontradoException("Motivo no encontrado"));}private ClienteResponse cliente(Cliente c){return new ClienteResponse(c.getId(),c.getRazonSocial(),c.getRut(),c.getContacto(),c.getCorreo(),c.getTelefono(),c.getDireccion(),c.getSlaHoras(),c.isActivo());}private EquipoResponse equipo(Equipo e){return new EquipoResponse(e.getId(),e.getClienteId(),e.getTipo(),e.getMarca(),e.getModelo(),e.getSerie(),e.getUbicacion(),e.isExterior(),e.isActivo());}private MotivoResponse motivo(MotivoCatalogo m){return new MotivoResponse(m.getId(),m.getTipo(),m.getTexto(),m.isActivo());}
}
